tool_input.command:
$targets = @(
  "$env:TEMP\nginx-ui-bak-20261124_145615.zip",
  "$env:TEMP\deploy-dashboard-verify.png",
  "$env:TEMP\ab_sess.txt",
  "$env:TEMP\nginx-ui-bak-path.txt"
)
Write-Output "TEMP=$env:TEMP"
foreach ($t in $targets) {
  $resolved = [System.IO.Path]::GetFullPath($t)
  $exists = Test-Path -LiteralPath $resolved
  $size = if ($exists -and -not (Test-Path -LiteralPath $resolved -PathType Container)) { (Get-Item -LiteralPath $resolved).Length } else { 'N/A' }
  Write-Output "$exists | $size | $resolved"
}

$tempRoot = [System.IO.Path]::GetFullPath($env:TEMP).TrimEnd('\') + '\'
$names = @(
  'nginx-ui-bak-20261124_145615.zip',
  'deploy-dashboard-verify.png',
  'ab_sess.txt',
  'nginx-ui-bak-path.txt'
)
foreach ($n in $names) {
  $resolved = [System.IO.Path]::GetFullPath((Join-Path $env:TEMP $n))
  if ($resolved.StartsWith($tempRoot, [System.StringComparison]::OrdinalIgnoreCase) -and (Test-Path -LiteralPath $resolved)) {
    Remove-Item -LiteralPath $resolved -Force
    Write-Output "DELETED: $resolved (exists after=$(Test-Path -LiteralPath $resolved))"
  } else {
    Write-Output "SKIPPED (prefix mismatch or missing): $resolved"
  }
}

